<?php get_header(); ?><main class="litano-section"><div class="litano-container"><div class="litano-eyebrow">LITANO STORE / PRECIOUS METALS</div><h1>Store</h1><div class="litano-store-toolbar"><input id="litano-store-search" type="search" placeholder="Search bullion"><select id="litano-metal-filter"><option value="">All metals</option><option value="gold">Gold</option><option value="silver">Silver</option><option value="platinum">Platinum</option><option value="palladium">Palladium</option></select><select id="litano-weight-filter"><option value="">All weights</option><option value="1 oz">1 oz</option><option value="100 g">100 g</option><option value="1 kg">1 kg</option></select></div><p class="litano-notice">Use the Store filters to browse products. Final price, inventory, taxes and shipping are confirmed before settlement.</p><div id="litano-store-products"><?php echo do_shortcode('[litano_catalog]'); ?></div></div></main><script>document.addEventListener('DOMContentLoaded',function(){const search=document.getElementById('litano-store-search'),metal=document.getElementById('litano-metal-filter'),weight=document.getElementById('litano-weight-filter');function filter(){document.querySelectorAll('.litano-product-card').forEach(function(card){const text=card.innerText.toLowerCase(),q=search.value.toLowerCase(),m=metal.value.toLowerCase(),w=weight.value.toLowerCase();card.style.display=(!q||text.includes(q))&&(!m||text.includes(m))&&(!w||text.includes(w))?'block':'none';});}search.addEventListener('input',filter);metal.addEventListener('change',filter);weight.addEventListener('change',filter);});</script><?php get_footer(); ?>
